// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount) public {
        // admissible domain: deposit must exceed MinDeposit (1 ether)
        amount = bound(amount, 1 ether + 1, 1000 ether);

        // adversarial environment: a re-entrant logger whose AddMessage
        // triggers ONE full re-entrant Deposit from the attacker contract
        ReenteringLogger logger = new ReenteringLogger();
        Attacker attacker = new Attacker(c, logger);
        logger.setAttacker(address(attacker));

        vm.deal(address(attacker), 3 * amount);
        attacker.attack(amount);

        // general rule: after the outer Deposit plus its one re-entrant inner
        // Deposit (each of `amount`), and the outer credit applied around the
        // log callback, the recorded balance must be exactly 3 * amount.
        assertTrue(c.balances(address(attacker)) == 3 * amount);
    }
}

contract ReenteringLogger {
    address public attacker;
    function setAttacker(address a) external { attacker = a; }
    function AddMessage(address, uint, string memory) public {
        if (attacker != address(0) && !Attacker(attacker).entered()) {
            Attacker(attacker).reenter();
        }
    }
}

contract Attacker {
    C public c;
    ReenteringLogger public logger;
    uint256 public amt;
    bool public entered;

    constructor(C _c, ReenteringLogger _l) { c = _c; logger = _l; }

    function attack(uint256 a) external {
        amt = a;
        entered = false;
        c.Deposit{value: a}();
    }

    function reenter() external {
        entered = true;
        c.Deposit{value: amt}();
    }

    receive() external payable {}
}

contract InvMutTest
{
    C c;

    constructor(C _c) { c = _c; }

    function test() public
    {
        uint amount = c.MinDeposit();
        require(address(this).balance >= amount);
        c.Deposit{value: amount}();
        assert(c.balances(address(this)) == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}
